    private static void add(List<ComponentReferenceSpec> result, String id, String component,
            String asset, double width, double height, int[] steps,
            VisionPoint[] corners, VisionPoint[][] polygons) {
        List<List<VisionPoint>> regions = new ArrayList<>();
        for (VisionPoint[] polygon : polygons) regions.add(Arrays.asList(polygon));
        for (int step : steps) {
            result.add(ComponentReferenceSpec.builder(id + "_section_" + step,
                    component, component, width, height).jpegAssetPath(asset)
                    .assemblyStepNumber(step).maximumImageDimension(1280)
                    .polarityAnchorsVerified(false).featureRegionsNormalized(regions)
                    .planarReferenceCornersNormalized(corners[0], corners[1], corners[2], corners[3])
                    .build());
        }
    }
